SELECT id, workspace_id, entity_type, entity_id, actor_id, actor_name,
       action, detail, created_at
FROM work_activity
WHERE workspace_id = #{workspaceId}
  AND entity_type = #{entityType}
  AND entity_id = #{entityId}
ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM work_activity
WHERE workspace_id = #{workspaceId}
  AND entity_type = #{entityType}
  AND entity_id = #{entityId}

